def share_text():
    items=["기기 도움을 부탁드려요.",f"기기: {s.device or '아직 확인 안 함'}",f"문제: {s.topic or '아직 선택 안 함'}"]
    items += ["시도했다고 표시한 안내:"] + ([f"- {a}" for a in s.attempts] or ["- 아직 없어요."])
    items += [f"찾기 어려움 표시: {s.total_misses}회",f"현재 결과: {s.result or '아직 해결 확인 전'}","사진·연락처·대화 원문은 포함하지 않았어요."]
    return "\n".join(items)

